 *   <li>指纹覆盖 requestId、操作类型与全部业务字段；</li>
 *   <li>同键同参：返回首次结果，包括首次业务拒绝（422/409），响应体重放标记 replayed=true；</li>
 *   <li>同键异参：返回 409，不执行业务、不产生新分次；</li>
 *   <li>并发同键：唯一约束决胜，负者重读首次结果返回。</li>
 * </ul>
 * 模板不自行开启事务，参与调用方 Service 的事务边界。
 */
@Component
public class IdempotencyTemplate {

    private final WorkflowRepository workflow;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public IdempotencyTemplate(WorkflowRepository workflow, ObjectMapper objectMapper, Clock clock) {
        this.workflow = workflow;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    /**
     * 按 requestId 幂等执行业务动作。动作的业务成功与业务拒绝（{@link ApiException}）均作为首次结果留痕。
     *
     * @param operation 操作类型
     * @param requestId 幂等键
     * @param params    参与指纹的全部业务字段
     * @param action    首次执行动作
     * @return 首次结果或重放结果；首次拒绝时异常仍向上抛出由控制器映射，重放拒绝则以结果对象返回
     */
    public RecordedResponse execute(OperationType operation, String requestId, Map<String, ?> params,
                                    Supplier<RecordedResponse> action) {
        String fingerprint = Fingerprint.of(operation, requestId, params);
        Optional<IdempotentRow> existing = workflow.findIdempotent(requestId);
        if (existing.isPresent()) {
            return replayOrConflict(existing.get(), fingerprint);
        }

        RecordedResponse result;
        try {
            result = action.get();
        } catch (ApiException rejected) {
            // 首次业务拒绝同样留痕，随后原样抛出由全局异常处理器映射。
            persistFirst(requestId, operation, fingerprint,
                    new RecordedResponse(rejected.getHttpStatus(),
                            new RejectionBody(rejected.getCode(), rejected.getMessage(),
                                    rejected.isAlert(), java.util.List.of())));
            throw rejected;
        }
        persistFirst(requestId, operation, fingerprint, result);
        return result;
    }

    private void persistFirst(String requestId, OperationType operation, String fingerprint,
                              RecordedResponse result) {
        try {
            workflow.insertIdempotent(requestId, operation.name(), fingerprint,
                    result.httpStatus(), writeJson(result.body()), LocalDateTime.now(clock));
        } catch (DuplicateKeyException concurrent) {
            // 并发同键：另一个事务已提交首次结果，重读后按重放/冲突处理，由调用方向上返回。
            IdempotentRow row = workflow.findIdempotent(requestId)
                    .orElseThrow(() -> ApiException.conflict("IDEMPOTENCY_RACE",
                            "并发请求冲突后未能读取首次结果，requestId=" + requestId));
            RecordedResponse replayed = replayOrConflict(row, fingerprint);
            throw new ReplayedResultException(replayed);
        }
    }

    private RecordedResponse replayOrConflict(IdempotentRow row, String fingerprint) {
        if (!row.fingerprint().equals(fingerprint)) {
            throw ApiException.conflict("IDEMPOTENCY_FINGERPRINT_CONFLICT",
                    "requestId=" + row.requestId() + " 已绑定不同业务参数，拒绝执行（409）");
        }
        Object replayedBody = markReplayed(readJson(row.responseJson()));
        return new RecordedResponse(row.httpStatus(), replayedBody);
    }

    /** 重放响应在保留首次业务字段的前提下，将 replayed 标记置为 true。 */
    @SuppressWarnings("unchecked")
    private Object markReplayed(Object body) {
        if (body instanceof Map<?, ?> map && map.containsKey("replayed")) {
            Map<String, Object> mutable = new LinkedHashMap<>((Map<String, Object>) map);
            mutable.put("replayed", true);
            return mutable;
        }
        return body;
    }

    private String writeJson(Object body) {
        try {
            return objectMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("幂等响应序列化失败", e);
        }
    }

    private Object readJson(String json) {
        try {
            return objectMapper.readValue(json, Object.class);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("幂等响应反序列化失败", e);
        }
    }

    /** 并发负者读到胜者首次结果时的内部载体，由服务层转换为返回值。 */
    public static class ReplayedResultException extends RuntimeException {
        private final transient RecordedResponse result;

        public ReplayedResultException(RecordedResponse result) {
            super(null, null, false, false);
            this.result = result;
        }

        public RecordedResponse getResult() {
            return result;
        }
    }
}

